package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class SemProductChecks {
    private static int checks;
    private static void require(boolean condition,String label){checks++;if(!condition)throw new AssertionError(label);}
    private static void rejects(Runnable action){try{action.run();throw new AssertionError("Unsupported product model accepted");}catch(IllegalArgumentException expected){checks++;}}
    private static SemModel.Model observed(int predictors){int k=predictors+1;List<String> names=new ArrayList<>();for(int i=0;i<predictors;i++)names.add("X"+i);names.add("Y");double[][] a=new double[k][k],s=new double[k][k];List<SemModel.Parameter> parameters=new ArrayList<>();for(int i=0;i<k;i++){s[i][i]=1;parameters.add(new SemModel.Parameter("Variance "+i,List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,i,i)),1,1,1e-8,null));}for(int i=0;i<predictors;i++){a[predictors][i]=.2;parameters.add(new SemModel.Parameter("Slope "+i,List.of(new SemModel.Location(SemModel.Kind.DIRECTED,predictors,i)),.2,1));for(int j=0;j<i;j++)parameters.add(new SemModel.Parameter("Cov "+i+" "+j,List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,i,j)),0,1));}return new SemModel.Model(names,java.util.stream.IntStream.range(0,k).toArray(),a,s,new double[k],parameters);}
    private static SemModel.Model latent(){int p=7,k=9;List<String> names=List.of("X1","X2","X3","Z1","Z2","Z3","Y","X","Z");double[][] a=new double[k][k],s=new double[k][k];List<SemModel.Parameter> parameters=new ArrayList<>();for(int i=0;i<k;i++){s[i][i]=i<6?.2:1;parameters.add(new SemModel.Parameter("Variance "+i,List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,i,i)),s[i][i],1,1e-8,null));}for(int factor=0;factor<2;factor++)for(int indicator=0;indicator<3;indicator++){int row=3*factor+indicator;a[row][7+factor]=indicator==0?1:.8;if(indicator!=0)parameters.add(new SemModel.Parameter("Loading "+row,List.of(new SemModel.Location(SemModel.Kind.DIRECTED,row,7+factor)),.8,1));}for(int factor=7;factor<9;factor++){a[6][factor]=.3;parameters.add(new SemModel.Parameter("Slope "+factor,List.of(new SemModel.Location(SemModel.Kind.DIRECTED,6,factor)),.3,1));}parameters.add(new SemModel.Parameter("Cov X Z",List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,7,8)),.2,1));return new SemModel.Model(names,java.util.stream.IntStream.range(0,p).toArray(),a,s,new double[k],parameters);}
    private static void archive(JsonObject item)throws Exception{var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonObject project=new JsonObject();project.add("observations",item.get("observations"));JsonArray names=new JsonArray();for(int i=0;i<item.getAsJsonArray("observations").get(0).getAsJsonArray().size();i++)names.add("V"+i);project.add("columnNames",names);project.add("blocks",new JsonArray());project.add("edges",new JsonArray());JsonObject numeric=new JsonObject();numeric.add("semProducts",item.get("point"));if(item.has("bootstrap"))numeric.add("bootstrap",item.get("bootstrap"));var report=org.brightstats.report.ReportArchive.create("CBSEM_PRODUCT_INDICATORS",project,numeric,new JsonArray(),List.of());var parsed=JsonParser.parseString(new GsonBuilder().serializeNulls().create().toJson(report)).getAsJsonObject();var restored=org.brightstats.report.SemProductReports.point(parsed);JsonObject replay=new JsonObject();replay.add("semProducts",gson.toJsonTree(restored));if(item.has("bootstrap"))replay.add("bootstrap",gson.toJsonTree(org.brightstats.report.SemProductReports.bootstrap(parsed)));require(report.get("results").equals(org.brightstats.report.ReportArchive.create("REPLAY",project,replay,new JsonArray(),List.of()).get("results")),"Product report preserves undefined numerics and options");}
    public static void main(String[] args)throws Exception{Random random=new Random(962);var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray cases=new JsonArray();var options=new CovarianceSem.Options(1500,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,false,.95,CovarianceSem.Information.EXPECTED);
        for(int variant=0;variant<4;variant++){int n=variant==1?600:90;double[][] data=new double[n][variant==1?7:variant==2?4:3];for(var row:data){double x=random.nextGaussian(),z=.3*x+Math.sqrt(.91)*random.nextGaussian(),w=random.nextGaussian(),y=.6*x+.4*z+.5*(x*z-.3)+.4*random.nextGaussian();if(variant==1){for(int j=0;j<3;j++){row[j]=(j==0?1:.8)*x+.3*random.nextGaussian();row[3+j]=(j==0?1:.8)*z+.3*random.nextGaussian();}row[6]=y;}else if(variant==2){row[0]=x+1;row[1]=z-1;row[2]=w+.5;row[3]=y+.2*w+.2*x*w-.15*z*w+.35*x*z*w;}else{row[0]=x+2;row[1]=z-1;row[2]=y+1;}}var base=variant==1?latent():observed(variant==2?3:2);if(variant==3){List<SemModel.Parameter> parameters=new ArrayList<>(base.parameters());for(int i=0;i<base.variables().size();i++)parameters.add(new SemModel.Parameter("Mean "+i,List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,i,0)),0,1));base=new SemModel.Model(base.variables(),base.observed(),base.directed(),base.covariance(),base.intercepts(),parameters);}var settings=new CovarianceSem.Options(options.maxIterations(),options.gradientTolerance(),options.functionTolerance(),options.likelihood(),variant==3,options.confidence(),options.information());int[] factors=variant==1?new int[]{7,8}:variant==2?new int[]{0,1,2}:new int[]{0,1};int target=variant==1?6:variant==2?3:2;var specification=new SemProductIndicators.Specification(base,java.util.stream.IntStream.range(0,data[0].length).toArray(),List.of(new SemProductIndicators.Interaction("Interaction",factors,target,SemProductIndicators.Coefficient.defaults())),variant==1?Map.of(7,List.of(0,1,2),8,List.of(3,4,5)):Map.of(),List.of(new PathProcess.Probe("Low moderator",Map.of(factors[1],-1.)),new PathProcess.Probe("At means",Map.of()),new PathProcess.Probe("High moderator",Map.of(factors[1],1.))));var fit=SemProductIndicators.fit(data,specification,settings);require(fit.covariance().converged(),"Product SEM converged: "+variant+" "+fit.covariance().convergenceReason());require(fit.covariance().identified(),"Product SEM identified");require(fit.conditional().size()==3*factors.length,"Centered-factor conditional slopes");require(fit.prepared().products().size()==(variant==2?4:1),"Product hierarchy");int p=base.observed().length;double[][] prepared=fit.prepared().observations();for(int col=p;col<prepared[0].length;col++){double mean=0;for(var row:prepared)mean+=row[col]/n;require(Math.abs(mean)<1e-12,"Double centered product mean");}if(variant!=1){double[][] x=new double[n][prepared[0].length-1];double[] y=new double[n];for(int i=0;i<n;i++){y[i]=prepared[i][target];for(int j=0,next=0;j<prepared[i].length;j++)if(j!=target)x[i][next++]=prepared[i][j];}var regression=OlsRegression.fit(x,y);double[] beta=regression.coefficients();var observedVariables=fit.prepared().model().observed();for(int j=0,next=1;j<observedVariables.length;j++)if(j!=target){require(Math.abs(fit.covariance().directed()[target][observedVariables[j]]-beta[next++])<2e-5,"Saturated observed product SEM equals hierarchical OLS");}}else{int product=fit.prepared().products().getFirst().variable();require(Math.abs(fit.covariance().directed()[target][product]-.5)<.16,"Latent interaction recovery");}
            if(variant==1){final var sourceSpec=specification;final var sourceData=data;double[][] endogenous=base.directed();endogenous[7][8]=.1;var endogenousBase=new SemModel.Model(base.variables(),base.observed(),endogenous,base.covariance(),base.intercepts(),base.parameters());rejects(()->SemProductIndicators.prepare(sourceData,new SemProductIndicators.Specification(endogenousBase,sourceSpec.columns(),sourceSpec.interactions(),sourceSpec.indicatorBlocks())));double[][] correlated=base.covariance();correlated[0][3]=correlated[3][0]=.1;var correlatedBase=new SemModel.Model(base.variables(),base.observed(),base.directed(),correlated,base.intercepts(),base.parameters());rejects(()->SemProductIndicators.prepare(sourceData,new SemProductIndicators.Specification(correlatedBase,sourceSpec.columns(),sourceSpec.interactions(),sourceSpec.indicatorBlocks())));var allFree=new ArrayList<>(base.parameters());allFree.add(new SemModel.Parameter("Free marker",List.of(new SemModel.Location(SemModel.Kind.DIRECTED,0,7)),1,1));var noMarker=new SemModel.Model(base.variables(),base.observed(),base.directed(),base.covariance(),base.intercepts(),allFree);rejects(()->SemProductIndicators.prepare(sourceData,new SemProductIndicators.Specification(noMarker,sourceSpec.columns(),sourceSpec.interactions(),sourceSpec.indicatorBlocks())));int[] bad=sourceSpec.columns();bad[0]=999;rejects(()->SemProductIndicators.prepare(sourceData,new SemProductIndicators.Specification(sourceSpec.base(),bad,sourceSpec.interactions(),sourceSpec.indicatorBlocks())));rejects(()->new SemProductIndicators.Interaction("Duplicate",new int[]{7,7},6,SemProductIndicators.Coefficient.defaults()));}
            JsonObject item=new JsonObject();item.add("observations",gson.toJsonTree(data));item.add("specification",gson.toJsonTree(specification));item.add("options",gson.toJsonTree(settings));item.add("point",gson.toJsonTree(fit));if(variant==0||variant==1){var bootOptions=new Bootstrap.Options(40,918,.95,variant==0?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var bootstrap=SemProductIndicators.bootstrap(data,specification,settings,bootOptions,null);require(bootstrap.inference().successful()==40,"Product SEM bootstrap");item.add("bootstrap",gson.toJsonTree(bootstrap.inference()));}archive(item);cases.add(item);
        }Thread.currentThread().interrupt();try{SemProductIndicators.prepare(new double[][]{{1,2,3},{2,3,4},{3,4,6}},new SemProductIndicators.Specification(observed(2),new int[]{0,1,2},List.of(new SemProductIndicators.Interaction("XZ",new int[]{0,1},2,SemProductIndicators.Coefficient.defaults()))));throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"checks\":"+checks+",\"cases\":"+cases.size()+"}");
    }
}
